WITH not_flagged AS (SELECT s.* FROM sessions s WHERE EXISTS (SELECT 1 FROM web_events c WHERE c.session_id = s.id AND c.page IS NOT NULL)), with_latest AS (SELECT s.*, latest.web_event_event_time FROM not_flagged s JOIN LATERAL (SELECT c.event_time AS web_event_event_time FROM web_events c WHERE c.session_id = s.id ORDER BY c.duration_sec DESC, c.id DESC LIMIT 1) latest ON TRUE), enriched AS (SELECT *, FIRST_VALUE(country, TRUE) OVER w_running AS first_known_country, LAST_VALUE(browser) IGNORE NULLS OVER (PARTITION BY browser ORDER BY web_event_event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_browser, LAST_VALUE(browser) IGNORE NULLS OVER (PARTITION BY device ORDER BY web_event_event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_browser_2 FROM with_latest WINDOW w_running AS (PARTITION BY customer_id, country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), gaps AS (SELECT *, CASE WHEN web_event_event_time - LAG(web_event_event_time) OVER (PARTITION BY customer_id ORDER BY web_event_event_time, id) > INTERVAL '60' DAY THEN 1 ELSE 0 END AS session_start_flag FROM enriched), islands AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY customer_id ORDER BY web_event_event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps), not_flagged_sessions AS (SELECT s.* FROM islands s WHERE NOT EXISTS (SELECT 1 FROM web_events c WHERE c.session_id = s.id AND c.event_time < s.web_event_event_time)) SELECT s.id, s.customer_id, s.browser, s.started_at, s.country, s.first_known_country, s.session_start_flag, s.session_id, CASE WHEN browser RLIKE '^(Safari|Firefox)$' THEN 'EXTENDED' ELSE 'PRIORITY' END AS browser_zone, (SELECT MIN(s2.monthly_fee) FROM subscriptions s2 WHERE s2.customer_id = s.customer_id) AS min_subscription_monthly_fee FROM not_flagged_sessions s ORDER BY min_subscription_monthly_fee DESC
